import { component$ } from "@qwik.dev/core";
import { useDocumentHead, useLocation } from "@qwik.dev/router";
import {
  TWYNE_SITE_ORIGIN,
  canonicalUrl,
  isPrivateWorkspacePath,
} from "../../utils/seo";

/**
 * The RouterHead component is placed inside of the document `<head>` element.
 */
export const RouterHead = component$(() => {
  const head = useDocumentHead();
  const loc = useLocation();

  const ogImage = `${TWYNE_SITE_ORIGIN}/og-image.png`;
  const pageUrl = canonicalUrl(loc.url);

  // Keys (name or property) a route already declared — render site-wide
  // social defaults only when the route hasn't overridden them.
  const declared = new Set(
    head.meta.map((m) => m.property ?? m.name).filter(Boolean) as string[],
  );

  const title = head.title || "Twyne — An Editorial Room for Writers";
  const description =
    (head.meta.find((m) => m.name === "description")?.content as string) ??
    "Twyne is a writer-first editing room. Start from an interview, then draft with a brief, editorial personas, rubric review, and citation detection.";

  const socialDefaults: Array<{
    property?: string;
    name?: string;
    content: string;
  }> = [
    { property: "og:type", content: "website" },
    { property: "og:site_name", content: "Twyne" },
    { property: "og:title", content: title },
    { property: "og:description", content: description },
    { property: "og:url", content: pageUrl },
    { property: "og:image", content: ogImage },
    { property: "og:image:width", content: "1200" },
    { property: "og:image:height", content: "630" },
    { property: "og:image:alt", content: "Twyne — The Editorial Room" },
    { name: "twitter:card", content: "summary_large_image" },
    { name: "twitter:title", content: title },
    { name: "twitter:description", content: description },
    { name: "twitter:image", content: ogImage },
  ].filter((m) => !declared.has((m.property ?? m.name) as string));

  const privateWorkspace = isPrivateWorkspacePath(loc.url.pathname);

  return (
    <>
      <title>{title}</title>

      <link rel="canonical" href={pageUrl} />
      <meta name="viewport" content="width=device-width, initial-scale=1.0" />

      {/* Favicons / app icons */}
      <link rel="icon" type="image/svg+xml" href="/assets/griffin-mark.svg" />
      <link rel="icon" type="image/png" sizes="32x32" href="/icon-192.png" />
      <link rel="alternate icon" href="/favicon.ico" sizes="48x48" />
      <link
        rel="apple-touch-icon"
        sizes="180x180"
        href="/apple-touch-icon.png"
      />
      {/*
        Browser chrome color. `media` lets the browser pick without any JS —
        the light entry is the default and the dark one only applies when the
        OS asks for dark. The color tracks the OS scheme only; an explicit
        preset pick in the appearance settings is not mirrored here.
      */}
      <meta
        name="theme-color"
        media="(prefers-color-scheme: light)"
        content="#9c1a1f"
      />
      <meta
        name="theme-color"
        media="(prefers-color-scheme: dark)"
        content="#191714"
      />

      {/* Site-wide social defaults (routes may override any key) */}
      {socialDefaults.map((m) => (
        <meta key={m.property ?? m.name} {...m} />
      ))}

      {privateWorkspace && !declared.has("robots") && (
        <meta name="robots" content="noindex, nofollow, noarchive" />
      )}

      {head.meta.map((m) => (
        <meta key={m.key} {...m} />
      ))}

      {head.links.map((l) => (
        <link key={l.key} {...l} />
      ))}

      {head.styles.map((s) => (
        <style
          key={s.key}
          {...s.props}
          {...(s.props?.dangerouslySetInnerHTML
            ? {}
            : { dangerouslySetInnerHTML: s.style })}
        />
      ))}

      {head.scripts.map((s) => (
        <script
          key={s.key}
          {...s.props}
          {...(s.props?.dangerouslySetInnerHTML
            ? {}
            : { dangerouslySetInnerHTML: s.script })}
        />
      ))}
    </>
  );
});
import { component$, $ } from "@qwik.dev/core";
import type { DocumentHead } from "@qwik.dev/router";
import { useNavigate } from "@qwik.dev/router";
import { LandingPage } from "../components/landing/landing-page";
import type { Folio } from "../types";
import { useAuth } from "../utils/auth-context";
import {
  loadFoliosFromIdb,
  saveFoliosToIdb,
  saveActiveFolioIdToIdb,
} from "../utils/idb";
import {
  captureProductEvent,
  type LandingCtaLocation,
} from "../utils/product-analytics";
import { TWYNE_HOME_STRUCTURED_DATA } from "../utils/seo";

/**
 * The landing page. Twyne-style: a magazine broadsheet the writer
 * unfolds before the first interview. Nobody is redirected off it:
 * "Start your brief" sends first-time local writers to /onboarding and
 * signed-in writers to /dossier/create, and returning writers take the
 * header link to the desk when they want it.
 */
export default component$(() => {
  const nav = useNavigate();
  const auth = useAuth();

  // The front page stays the front page. Returning writers used to be bounced
  // straight to /editor the moment a brief existed, which made the landing
  // page — and every link on it — unreachable for anyone who had ever written
  // anything. The desk is one click away in the header instead.

  const startBrief = $((location: LandingCtaLocation) => {
    const signedIn = Boolean(auth.value.user);
    void captureProductEvent("landing_cta_clicked", {
      location,
      destination: signedIn ? "dossier" : "onboarding",
    });
    void nav(signedIn ? "/dossier/create/" : "/onboarding/");
  });

  const skipToEditor = $(async (location: LandingCtaLocation) => {
    // Going straight to the desk without an interview: make sure there's a
    // folio to write into so /editor doesn't bounce back to onboarding.
    const folios = await loadFoliosFromIdb();
    if (folios.length === 0) {
      const folio: Folio = {
        id: crypto.randomUUID(),
        name: "Current draft",
        type: "draft",
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };
      await saveFoliosToIdb([folio]);
      await saveActiveFolioIdToIdb(folio.id);
      void captureProductEvent("folio_created", {
        source: "landing",
        folio_type: folio.type,
      });
    }
    void captureProductEvent("landing_cta_clicked", {
      location,
      destination: "editor",
    });
    void nav("/editor/");
  });

  return (
    <main class="paper-fade-in">
      <LandingPage onStartBrief$={startBrief} onSkipToEditor$={skipToEditor} />
    </main>
  );
});

export const head: DocumentHead = {
  title: "Twyne — An Editorial Room for Writers",
  meta: [
    {
      name: "description",
      content:
        "Twyne is an anti-tabula-rasa writing workspace. Start with an interview; a room of editors reads from the brief you build.",
    },
    {
      property: "og:title",
      content: "Twyne — The Writer's Room",
    },
    {
      property: "og:description",
      content:
        "Write with a room full of editors. Twyne starts with an interview, a seeded brief, citation detection, and structured feedback.",
    },
  ],
  scripts: [
    {
      props: { type: "application/ld+json" },
      script: JSON.stringify(TWYNE_HOME_STRUCTURED_DATA),
    },
  ],
};
