            backgroundColor: "var(--color-paper-soft)",
          },
          ".cm-cursor": { borderLeftColor: "var(--color-ink)" },
          ".cm-foldPlaceholder": {
            background: "var(--color-paper-soft)",
            color: "var(--color-ink-light)",
            border: "1px solid var(--color-paper-3)",
