              effects: foldEffect.of({
                from: view.state.doc.line(1).to,
                to: end + "// twyne-document:body".length,
              }),
              selection: {
                anchor: Math.min(
                  next.length,
                  end + "// twyne-document:body".length + 1,
                ),
              },
            });
        }
      } finally {
        settingValue = false;
      }
    },
    setReadOnly(value: boolean) {
      view.dispatch({
        effects: readOnly.reconfigure(EditorState.readOnly.of(value)),
      });
    },
    focus() {
      view.focus();
    },
    destroy() {
      view.destroy();
    },
  };
}

