  /** Stable id for the pass (used for UI keys, not persistence). */
  id: string;
  kind: ResearchTargetKind;
  /** The passage verbatim just as it appears in the draft. */
  anchor: string;
  /** Why this specific thing should not stand uncited. */
  reason: string;
  /** The precise query the search providers should receive for thi…242 tokens truncated…nuscript.
 */
export interface DraftContentDetail {
  /** Serialized manuscript HTML — the form that gets persisted. */
  html: string;
  /** Plain text, blocks separated by a blank line (Tiptap's default). */
