server/build/q-pVpNxXx-.js:1:import{C as e,at as t,st as n}from"./q-vvfY_S2w.js";import{t as r}from"./q-BEz9pbFr.js";var i=e(`s_ia4WYUlpi7s`);i.s(()=>t(r,null,{title:`Privacy Policy`,lead:`What Twyne stores, where it lives, and who can see it.`,updated:`15 June 2026`,toc:[{id:`local-first`,label:`Local-first by default`},{id:`sign-in`,label:`When you sign in`},{id:`authentication`,label:`Authentication`},{id:`ai-providers`,label:`AI providers & your API keys`},{id:`analytics`,label:`Analytics`},{id:`publishing`,label:`Publishing`},{id:`payments`,label:`Payments`},{id:`controls`,label:`Your controls`},{id:`security`,label:`Security & retention`},{id:`third-party`,label:`Third-party services`},{id:`changes`,label:`Changes`},{id:`contact`,label:`Contact`}]},[t(`div`,null,{class:`doc-callout`},t(`p`,null,null,`This policy explains how Twyne handles information when you use the writing desk, sync, hosted AI, publishing, analytics, and payments. It is written for clarity; if any feature says it will send data to a third party, the sections below explain when and why.`,3,null),3,null),t(`h2`,null,{id:`local-first`,class:`doc-h2`},`Local-first by default`,3,null),t(`p`,null,{class:`doc-p`},`Twyne is designed to keep your writing on your own device. Your brief, folios, drafts, persona notes, and settings are stored in your browser's IndexedDB. If you never sign in, this data does not leave your machine through Twyne.`,3,null),t(`p`,null,{class:`doc-p`},`Browser storage is controlled by the browser profile and device where you use Twyne. Clearing site data, using private browsing, resetting the app, or losing access to that device may remove local-only work, so you should export important folios or enable sync if you want a backup.`,3,null),t(`h2`,null,{id:`sign-in`,class:`doc-h2`},`When you sign in`,3,null),t(`p`,null,{class:`doc-p`},`Creating an account and signing in enables sync: your folios and related data are sent to our backend so you can access them on other devices. We store this data to provide the sync feature and associate it with your account identifier. You can delete it by deleting your account or clearing your synced data.`,3,null),t(`p`,null,{class:`doc-p`},`Synced data may include your projects, briefs, folios, comments, citations, persona settings, publishing state, timestamps, and other records needed to keep the writing workspace consistent across devices. We do not sell your synced writing or use it to train general-purpose AI models.`,3,null),t(`h2`,null,{id:`authentication`,class:`doc-h2`},`Authentication`,3,null),t(`p`,null,{class:`doc-p`},`You sign in to Twyne with a Not Organic account. Not Organic verifies your identity and tells Twyne your account DID; we store the minimum identifiers needed to authenticate you and maintain your session. If you connect a PDS for publishing, that connection uses ATProto OAuth with your chosen provider.`,3,null),t(`p`,null,{class:`doc-p`},`Authentication records may include your Not Organic DID and handle, display name, account id, session tokens, and — when you connect a PDS for publishing — your ATProto handle and OAuth tokens or token identifiers. These records are used for login, account security, sync, publishing, and support.`,3,null),t(`h2`,null,{id:`ai-providers`,class:`doc-h2`},`AI providers and your API keys`,3,null),t(`p`,null,{class:`doc-p`},`When you use AI features with your own key (BYOK), your key is stored locally in your browser. Remote AI requests, including your key and the text you send, pass through Twyne to the provider you chose. The relay does not store or log request bodies or keys. Local model requests connect directly from your device. Those requests, including the text you send for review, are processed by that third-party provider under their privacy policy. We do not need your API key to be stored on our servers.`,3,null),t(`p`,null,{class:`doc-p`},`If you use hosted AI instead of BYOK, the prompt, relevant draft text, brief, selected persona, and AI response are processed through Twyne's backend and the configured model provider. Hosted AI requests may also be recorded as AI observability events so we can debug failures, evaluate output quality, and understand cost and latency. These events may include truncated prompt and response text.`,3,null),t(`p`,null,{class:`doc-p`},`In the desktop app, local model features may run through a loopback service on your own computer when available. In that mode, the local model provider is managed by the desktop shell and does not require a cloud API key.`,3,null),t(`h2`,null,{id:`analytics`,class:`doc-h2`},`Analytics`,3,null),t(`p`,null,{class:`doc-p`},`We may use PostHog or similar product analytics to understand how Twyne is used, roll out feature flags, find errors, measure performance, and improve the product. Analytics may collect page views, feature usage, device and browser information, approximate location derived from network data, account identifiers for signed-in users, and event properties.`,3,null),t(`p`,null,{class:`doc-p`},`Twyne does not use product analytics to sell your writing. Some AI observability events may include prompt and output text as described above; ordinary page and feature events should not require draft contents. You can limit analytics through browser settings, content blockers, or any controls provided in the app.`,3,null),t(`h2`,null,{id:`publishing`,class:`doc-h2`},`Publishing`,3,null),t(`p`,null,{class:`doc-p`},`If you choose to publish a draft (for example to your ATProto / Bluesky PDS), that content becomes available according to the network you publish to. Published content may be cached or indexed by third parties even after you remove it.`,3,null),t(`p`,null,{class:`doc-p`},`For internal reading links or public share views, Twyne stores the published state and the content needed to render the shared view until you unpublish or delete it. Anyone with access to a public link may copy or redistribute what they can read.`,3,null),t(`h2`,null,{id:`payments`,class:`doc-h2`},`Payments`,3,null),t(`p`,null,{class:`doc-p`},`If paid plans are available and you subscribe, checkout and payment processing are handled through Not Organic checkout, with Paddle as the payment processor. Twyne sends the information needed to create checkout, such as your account identifier, product id, and, when available, email address. We store subscription status, product identifiers, payment-provider customer and subscription ids, current period information, and related webhook data needed to grant or revoke paid features.`,3,null),t(`h2`,null,{id:`controls`,class:`doc-h2`},`Your controls`,3,null),t(`ul`,null,{class:`doc-ul`},[t(`li`,null,null,`Export any folio (Markdown, HTML, text, or a .twyne.json backup).`,3,null),t(`li`,null,null,`Clear local data from your browser at any time.`,3,null),t(`li`,null,null,`Delete your account and synced data if you signed in.`,3,null),t(`li`,null,null,`Remove saved AI providers and API keys from Settings.`,3,null),t(`li`,null,null,`Unpublish shared or ATProto-published content where supported.`,3,null),t(`li`,null,null,`Use Twyne entirely offline and local-only by not signing in.`,3,null)],3,null),t(`h2`,null,{id:`security`,class:`doc-h2`},`Security and retention`,3,null),t(`p`,null,{class:`doc-p`},`We use reasonable technical and organizational measures to protect the data Twyne stores, including provider-managed infrastructure, access controls, and webhook signature verification for payment events. No system can be guaranteed perfectly secure. You are responsible for securing your own device, browser profile, account credentials, and third-party API keys.`,3,null),t(`p`,null,{class:`doc-p`},`We keep account, sync, subscription, and operational records for as long as needed to provide Twyne, meet legal or security obligations, resolve disputes, and maintain backups. Local-only browser data remains on your device until you delete it or your browser removes it.`,3,null),t(`h2`,null,{id:`third-party`,class:`doc-h2`},`Third-party services`,3,null),t(`p`,null,{class:`doc-p`},`Twyne relies on third-party services for infrastructure, authentication, AI providers, ATProto publishing, analytics, and payments. Those services process information under their own terms and privacy policies when you use the related feature. Examples include Convex and Better Auth for backend/auth flows, AI providers such as Anthropic, OpenAI, Google, Rivet, or OpenAI-compatible providers, PostHog for analytics and feature flags, ATProto services for PDS publishing, Not Organic for sign-in, the product checkout and wallet, and Paddle for payment processing.`,3,null),t(`h2`,null,{id:`changes`,class:`doc-h2`},`Changes`,3,null),t(`p`,null,{class:`doc-p`},`We may update this policy from time to time; the "last updated" date above reflects the latest revision. If a change materially affects how we handle your data, we will take reasonable steps to make the change visible in the product or on this page.`,3,null),t(`h2`,null,{id:`contact`,class:`doc-h2`},`Contact`,3,null),t(`p`,null,{class:`doc-p`},[`Questions about privacy can be sent to`,` `,t(`a`,null,{href:`mailto:support@twyne.love`},`support@twyne.love`,3,null),`.`],3,null)],3,`4J_0`));var a=n(i),o={title:`Privacy Policy · Twyne`,meta:[{name:`description`,content:`Twyne's Privacy Policy: local-first storage, what syncs when you sign in, bring-your-own-key AI, analytics, and your data controls.`}]};export{a as default,o as head};
server/build/q-DhIqksUo.js:95:  `),c.s(()=>(r(l),n(`div`,null,{class:`min-h-screen bg-[var(--color-paper-soft)] text-[var(--color-ink)]`,style:{fontFamily:`var(--font-serif)`}},n(`div`,null,{class:`max-w-4xl mx-auto px-6 py-8`},[n(`div`,null,{class:`flex items-center justify-between mb-8`},[n(`div`,null,null,[n(`p`,null,{class:`dept-label mb-1`,style:{fontFamily:`var(--font-typewriter)`}},`Twyne`,3,null),n(`h1`,null,{style:{fontFamily:`var(--font-display)`,fontWeight:700,fontSize:`1.75rem`}},`The Manual`,3,null),n(`p`,null,{class:`doc-lead mt-2 !mb-0`},`A writer's guide to the editorial room.`,3,null)],3,null),n(e,null,{href:`/editor/`,class:`btn-paper text-sm`,style:{fontFamily:`var(--font-display)`}},`← Back to desk`,3,`Ln_0`)],3,null),n(`nav`,null,{class:`folio p-5 mb-8`},[n(`p`,null,{class:`text-[0.6rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-3`,style:{fontFamily:`var(--font-typewriter)`}},`Contents`,3,null),n(`div`,null,{class:`grid sm:grid-cols-2 gap-x-6`},[n(`a`,null,{href:`#launch-film`,class:`toc-link`},`Watch the launch film`,3,null),n(`a`,null,{href:`#account-and-live`,class:`toc-link`},`Sign-in & live voice`,3,null),n(`a`,null,{href:`#dossier`,class:`toc-link`},`I. The Dossier`,3,null),n(`a`,null,{href:`#room`,class:`toc-link`},`II. The Room of Editors`,3,null),n(`a`,null,{href:`#rubric`,class:`toc-link`},`III. The Galley Proof`,3,null),n(`a`,null,{href:`#marginalia`,class:`toc-link`},`IV. The Marginalia`,3,null),n(`a`,null,{href:`#apparatus`,class:`toc-link`},`V. The Apparatus`,3,null),n(`a`,null,{href:`#byok`,class:`toc-link`},`VI. Bring Your Own Key`,3,null),n(`a`,null,{href:`#privacy`,class:`toc-link`},`VII. Privacy & Your Data`,3,null),n(`a`,null,{href:`#folios`,class:`toc-link`},`VIII. Folios, Export & Share`,3,null),n(`a`,null,{href:`#manuscript-tools`,class:`toc-link`},`IX. Manuscript Tools`,3,null),n(`a`,null,{href:`#shortcuts`,class:`toc-link`},`X. Keyboard Shortcuts`,3,null)],3,null)],3,null),n(`section`,null,{id:`launch-film`,class:`doc-section`},[n(s,null,null,null,3,`Ln_1`),n(`p`,null,{class:`doc-p mt-5`},`The film follows your language choice in Preferences. French readers see the French edition, including narration and on-screen text; English and other languages use the English edition. With Automatic selected, Twyne follows your browser’s language preferences.`,3,null)],1,null),n(`section`,null,{id:`account-and-live`,class:`doc-section`},[n(`h2`,null,{class:`doc-h2`},`Sign-in & Live Voice`,3,null),n(`p`,null,{class:`doc-p`},`Sign in with Not Organic to use your account, hosted credits and plan across devices. Twyne no longer offers email codes or its own passkeys. You can keep writing locally without signing in.`,3,null),n(`p`,null,{class:`doc-p`},`Open Talk from the compositor, an editor’s comment or the narration player to speak with an editor. Live shows captions, lets you mute the microphone, and can find passages or propose edits. Approve a proposed edit before it changes your manuscript. Switching folios ends the conversation; captions and microphone recordings are not saved.`,3,null),n(`p`,null,{class:`doc-p`},`Live requires a Pro plan or available Twyne welcome credit. A conversation reserves up to $0.50; delegated language requests have a separate $0.05 maximum each. The voice desk shows these limits before you start.`,3,null)],3,null),n(`section`,null,{id:`dossier`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section I`,3,null),n(`h2`,null,{class:`doc-h2`},`The Dossier`,3,null),n(`p`,null,{class:`doc-lead`},`Every piece worth writing needs a brief. The dossier is Twyne's way of keeping the writer honest about what they're trying to do.`,3,null),n(`p`,null,{class:`doc-p`},`Before the room opens, we ask seven questions. They are not optional flourishes — they are the spine of the editorial conversation. When you know your audience, your goal, your tone, your constraints, and what success looks like, the editors have something to grip. Without it, even the cleverest feedback is fishing in the dark.`,3,null),n(`p`,null,{class:`doc-p`},`The seven fields:`,3,null),n(`ul`,null,{class:`doc-ul`},[n(`li`,null,null,[n(`strong`,null,null,`Working Title`,3,null),` — A name the room can hold onto.`],3,null),n(`li`,null,null,[n(`strong`,null,null,`Format`,3,null),` — Essay, memo, chapter, dispatch, proposal…`],3,null),n(`li`,null,null,[n(`strong`,null,null,`Audience`,3,null),` — Name the actual reader, not a demographic.`],3,null),n(`li`,null,null,[n(`strong`,null,null,`Goal`,3,null),` — What should the piece accomplish?`],3,null),n(`li`,null,null,[n(`strong`,null,null,`Tone`,3,null),` — How should it feel, not just sound?`],3,null),n(`li`,null,null,[n(`strong`,null,null,`Constraints`,3,null),` — Sources to keep, jargon to avoid, anecdotes to protect.`],3,null),n(`li`,null,null,[n(`strong`,null,null,`Success Signal`,3,null),` — How will you know the draft has landed?`],3,null)],3,null),n(`div`,null,{class:`doc-callout`},n(`p`,null,null,[n(`strong`,null,null,`Pro tip:`,3,null),` You can refine the dossier at any time by clicking "Refine the dossier" in the masthead. The room picks up the new brief on the next pass.`],3,null),3,null)],3,null),n(`section`,null,{id:`room`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section II`,3,null),n(`h2`,null,{class:`doc-h2`},`The Room of Editors`,3,null),n(`p`,null,{class:`doc-lead`},`Five resident voices. Each reads with a different lens. Together they cover the ground a single editor can't.`,3,null),n(`h3`,null,{class:`doc-h3`},`Mlle. Sceptique — The Devil's Advocate`,3,null),n(`p`,null,{class:`doc-p`},`Hunts the unstated assumption, the soft claim, the argument that quietly evades its strongest objection. When she speaks, listen — she is testing whether your draft would survive a hostile reader.`,3,null),n(`h3`,null,{class:`doc-h3`},`Sœur Encourageante — The Patron of Strengths`,3,null),n(`p`,null,{class:`doc-p`},`Reads for the alive paragraph — the one with a real sentence in it — and tells you to protect it. Not empty praise; specific, earned defence of what's working.`,3,null),n(`h3`,null,{class:`doc-h3`},`Professeur Athenæum — The Scholar`,3,null),n(`p`,null,{class:`doc-p`},`Points to where citation is owed, where evidence wants weight, where definition would clean a sentence. Think of him as the footnotes you haven't written yet.`,3,null),n(`h3`,null,{class:`doc-h3`},`M. Le Stylo — The Copy Chief`,3,null),n(`p`,null,{class:`doc-p`},`Carries the blue pencil. Catches diction, rhythm, repetition, and any sentence that does not earn its place. He is the one who will tell you to cut your favourite line.`,3,null),n(`h3`,null,{class:`doc-h3`},`Le Lecteur — The Target Reader`,3,null),n(`p`,null,{class:`doc-p`},`Reads as your stated audience would — confused here, engaged there, won over (or not) by the close. If Le Lecteur is lost, your audience is lost.`,3,null),n(`div`,null,{class:`doc-callout`},n(`p`,null,null,[n(`strong`,null,null,`Custom editors:`,3,null),` Visit`,` `,n(e,null,{href:`/personas`,class:`underline hover:text-[var(--color-vermilion)]`},`the Room of Editors`,3,`Ln_2`),` `,`to add, edit, or rearrange your cast. Each editor needs a name, a role, and a description of their voice. The AI uses these to stay in character.`],3,null),3,null),n(`h3`,null,{class:`doc-h3`},`Changing the Model`,3,null),n(`p`,null,{class:`doc-p`},[`Each editor's voice is shaped by the model that reads for them. A careful, precise model makes Mme. Sceptique sharper. A warmer model makes Sœur Encourageante more generous. Go to`,` `,n(e,null,{href:`/settings`,class:`underline hover:text-[var(--color-vermilion)]`},`Preferences`,3,`Ln_3`),` `,`to assign different models to different tasks — the room adapts.`],3,null)],3,null),n(`section`,null,{id:`rubric`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section III`,3,null),n(`h2`,null,{class:`doc-h2`},`The Galley Proof`,3,null),n(`p`,null,{class:`doc-lead`},`The rubric reads your draft in two ways: numbers the eye can see, and judges who read like people.`,3,null),n(`p`,null,{class:`doc-p`},[`The `,n(`strong`,null,null,`static features`,3,null),` are deterministic — sentence length distribution, type-token ratio, citation density, paragraph shape. These never call an API and never cost a token. They give you a cold, honest picture of the draft's mechanical health.`],3,null),n(`p`,null,{class:`doc-p`},[`The `,n(`strong`,null,null,`five judges`,3,null),` are the same personas from the room, but now they give a single integer score from 1 to 10 and a one-line rationale. The rubric combines their scores with the static features into an overall grade (A+ through F) and a short editorial note.`],3,null),n(`p`,null,{class:`doc-p`},`Grading scale:`,3,null),n(`ul`,null,{class:`doc-ul`},[n(`li`,null,null,[n(`strong`,null,{class:`text-[var(--color-accent-green)]`},`A range`,3,null),` `,`— Publishable or nearly so. Minor polish.`],3,null),n(`li`,null,null,[n(`strong`,null,{class:`text-[var(--color-accent-blue)]`},`B range`,3,null),` — Solid draft with clear, fixable issues.`],3,null),n(`li`,null,null,[n(`strong`,null,{class:`text-[var(--color-accent-amber)]`},`C range`,3,null),` `,`— Doing the work but needs a real pass.`],3,null),n(`li`,null,null,[n(`strong`,null,{class:`text-[var(--color-accent-red)]`},`D–F range`,3,null),` `,`— The important next pass is still ahead.`],3,null)],3,null),n(`div`,null,{class:`doc-callout`},n(`p`,null,null,[n(`strong`,null,null,`Interpreting the grade:`,3,null),` Most first drafts land in the C range. That is not failure; that is the honest place where writing starts. The rubric's job is to tell you where to push.`],3,null),3,null)],3,null),n(`section`,null,{id:`marginalia`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section IV`,3,null),n(`h2`,null,{class:`doc-h2`},`The Marginalia`,3,null),n(`p`,null,{class:`doc-lead`},`Threaded comments alongside the draft. Your own notes, plus the editors' voices when you ask them in.`,3,null),n(`p`,null,{class:`doc-p`},`Select any passage in the manuscript and click "Add comment" to pencil a margin note. Comments are folio-scoped — they travel with the draft, not the global state. Each comment can have replies, and you can ask any editor to weigh in by clicking "Ask an editor."`,3,null),n(`p`,null,{class:`doc-p`},`When an editor replies, their colour and voice are preserved so you know who is speaking. Strike a comment when you've addressed it; it softens into the background but stays in the archive.`,3,null)],3,null),n(`section`,null,{id:`apparatus`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section V`,3,null),n(`h2`,null,{class:`doc-h2`},`The Apparatus`,3,null),n(`p`,null,{class:`doc-lead`},`Research, bibliography, and citation — the machinery behind the prose.`,3,null),n(`p`,null,{class:`doc-p`},`The Apparatus has three jobs: find sources, save them, and cite them. As you write, it detects DOIs, URLs, ISBNs, and author-year references automatically. You can also search for sources by query — the panel fetches a shortlist with title, author, publisher, and a snippet. Save what matters to your bibliography.`,3,null),n(`p`,null,{class:`doc-p`},`Bibliographies are formatted in your chosen style — MLA, APA, or Chicago. Switch at any time; the saved entries reformat instantly. Copy the whole bibliography to your clipboard with one click.`,3,null),n(`div`,null,{class:`doc-callout`},n(`p`,null,null,[`The full Apparatus is available at`,` `,n(e,null,{href:`/apparatus`,class:`underline hover:text-[var(--color-vermilion)]`},`/apparatus`,3,`Ln_4`),`. The right-panel citation tab shows a quick view of detected references.`],3,null),3,null)],3,null),n(`section`,null,{id:`byok`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section VI`,3,null),n(`h2`,null,{class:`doc-h2`},`Bring Your Own Key`,3,null),n(`p`,null,{class:`doc-lead`},`Twyne works out of the box. But if you want to use your own AI models, your own keys, and your own cost envelope — you can.`,3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`Step 1: Add a provider.`,3,null),` Go to`,` `,n(e,null,{href:`/settings`,class:`underline hover:text-[var(--color-vermilion)]`},`Preferences`,3,`Ln_5`),` `,`and turn on "Bring Your Own Key." Add your OpenAI, Anthropic, or Google key. For other providers (Groq, Together, Rivet), use the "OpenAI-compatible" option with your base URL.`],3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`Step 2: Pick models per feature.`,3,null),` Not all tasks need the most expensive model. You might want Claude Sonnet for the full room convene (needs deep comprehension) and GPT-4o-mini for rubric judges (simple scoring). The per-feature grid lets you assign exactly that.`],3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`Step 3: Test the connection.`,3,null),` Each provider card has a "Test connection" button. It sends a cheap ping and shows latency. Green means go.`],3,null),n(`p`,null,{class:`doc-p`},`Supported providers:`,3,null),n(`ul`,null,{class:`doc-ul`},[n(`li`,null,null,`OpenAI (GPT-4o, GPT-4o-mini, o3-mini, …)`,3,null),n(`li`,null,null,`Anthropic (Claude Sonnet, Claude Haiku, …)`,3,null),n(`li`,null,null,`Google (Gemini 2.5 Flash, Gemini 2.5 Pro, …)`,3,null),n(`li`,null,null,`OpenAI-compatible (Groq, Together, Rivet, local servers, …)`,3,null)],3,null),n(`div`,null,{class:`doc-callout`},n(`p`,null,null,[n(`strong`,null,null,`Important:`,3,null),` Twyne does not fall back silently. If your key is invalid or the provider is down, you'll see an error and the app falls back to the server-side path (or local templates if the server is also unavailable). The draft is never blocked.`],3,null),3,null)],3,null),n(`section`,null,{id:`privacy`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section VII`,3,null),n(`h2`,null,{class:`doc-h2`},`Privacy & Your Data`,3,null),n(`p`,null,{class:`doc-lead`},`Your manuscript is yours. We intend to keep it that way.`,3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`API keys:`,3,null),` Saved in your browser’s IndexedDB. Remote BYOK requests pass through Twyne’s server relay, which forwards your key and request to the selected provider. Local model endpoints stay direct.`],3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`Drafts and folios:`,3,null),` Saved locally in your browser via IndexedDB. If you sign in, they sync to your own Convex account for cross-device access. They are not shared, sold, or used to train models.`],3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`AI calls:`,3,null),` When you BYOK, your draft text goes to the provider you chose, through the relay for remote endpoints. Hosted calls go through Convex and Not Organic. Provider processing and content-logging consent are managed in Not Organic.`],3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`Published pieces:`,3,null),` Only what you explicitly publish becomes public. Everything else stays private to your account.`],3,null)],3,null),n(`section`,null,{id:`folios`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section VIII`,3,null),n(`h2`,null,{class:`doc-h2`},`Folios, Export & Share`,3,null),n(`p`,null,{class:`doc-lead`},`One project. Many drafts. Each lives in its own folio.`,3,null),n(`p`,null,{class:`doc-p`},`Folios are separate documents within the same project. You might have a main draft, a scratch notes folio, and an outline. Switch between them from the left drawer. Each folio keeps its own word count, update time, and (optionally) its own layout settings.`,3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`Export`,3,null),` your folio as Markdown, standalone HTML, plain text, PDF, Word, Typst source, or a full Twyne backup (JSON with brief, folios, and content). Use the File menu in the masthead.`],3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`Share`,3,null),` a public reading view of any folio. Anyone with the link can read it; no one can edit it. Unpublish instantly.`],3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`Publish to your PDS`,3,null),` by connecting Bluesky or another ATProto provider in the Share dialog. This publishing connection is separate from your Not Organic sign-in. Twyne files a Standard.site publication and document in your own repository, serves a verifiable public reading page, and updates the same record when you re-publish. Unpublishing removes the document from your PDS.`],3,null),n(`p`,null,{class:`doc-p`},[n(`strong`,null,null,`PDF (Typst)`,3,null),` compiles your manuscript on this device with bundled fonts. You can cancel an export or download the .typ source. Equations, diagrams and unsupported content need the regular PDF export; Typst reports these limits before downloading.`],3,null)],3,null),n(`section`,null,{id:`manuscript-tools`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section IX`,3,null),n(`h2`,null,{class:`doc-h2`},`Manuscript Tools`,3,null),n(`p`,null,{class:`doc-lead`},`The manuscript surface now carries the structural tools of a full word processor without hiding the draft behind panels.`,3,null),n(`p`,null,{class:`doc-p`},[`Type `,n(`strong`,null,null,`/`,3,null),` at the start of a block to open the command menu. Use the outline to jump among headings, or drag a heading's section handle to move that section and all of its subsections in one undoable edit. Find and Replace supports whole words, case sensitivity, and regular expressions.`],3,null),n(`p`,null,{class:`doc-p`},`Tables support a dimension picker, captions, row and column tools, cell shading, alignment, borders, and reusable visual presets. Images can be dropped, pasted, or selected from disk; selecting an image reveals its alt text, caption, alignment, width, and upload status. Online images are stored with the folio, while deliberately offline work keeps an inline copy.`,3,null),n(`p`,null,{class:`doc-p`},`Inline and display equations accept LaTeX and render locally. Footnotes and endnotes can be edited beside their references, and the visible page header and footer can be edited directly in the page bands. These structures remain portable in HTML and Markdown exports.`,3,null)],3,null),n(`section`,null,{id:`shortcuts`,class:`doc-section`},[n(`p`,null,{class:`text-[0.65rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] mb-2`,style:{fontFamily:`var(--font-typewriter)`}},`Section X`,3,null),n(`h2`,null,{class:`doc-h2`},`Keyboard Shortcuts`,3,null),n(`p`,null,{class:`doc-p`},`These are the macOS labels. Windows and Linux use Ctrl wherever the list shows ⌘.`,3,null),n(a,null,{entries:u},null,3,`Ln_6`)],1,null)],1,null),1,`Ln_7`)));var d=i(c),f={title:`The Manual · Twyne`,meta:[{name:`description`,content:`The writer's guide to Twyne — the editorial room, the dossier, the galley proof, and bringing your own key.`}]};export{u as _auto_MANUAL_SHORTCUTS,d as default,f as head};
