import { createQwikRouter } from "@qwik.dev/router/middleware/node";
import { fileURLToPath } from "node:url";
import render from "./entry.ssr";

/**
 * The default export is the QwikCity adapter used by Vite preview.
 */
export default createQwikRouter({
  render,
  // Qwik 2 beta's middleware default is relative to its package, which points
  // outside this project once the entry is bundled into `server/`.
  static: { root: fileURLToPath(new URL("../dist", import.meta.url)) },
});
#!/usr/bin/env bash
# Railway build step: deploy Convex backend (when key is configured), then
# build the Qwik City frontend + SSR server.
#
# Gating: when CONVEX_DEPLOY_KEY is unset (frontend-only deploys, preview
# environments, local re-runs) we still build the frontend but skip the
# backend push.

set -euo pipefail

