    try {
      png = readFileSync(join(process.cwd(), "public", "og-image.png"));
    } catch {
      send(404, "Not found");
      return;
    }
  }

  send(
    new Response(png, {
      headers: { "Content-Type": "image/png" },
    }),
  );
