  const svg = buildSvg(input);
  const resvg = new Resvg(svg, {
    fitTo: { mode: "width", value: WIDTH },
    background: PAPER,
    font: {
      fontFiles: FONT_FILES,
      defaultFontFamily: "Fraunces",
      loadSystemFonts: false,
    },
