# Twyne social preview

Selected artwork: the writer's desk. Generated with the built-in imagegen tool. Final asset: `public/assets/social/twyne-writers-desk-v1.jpg` (1200 × 630 JPEG). The versioned URL is shared by Open Graph, Twitter cards, and homepage structured data.

## Generation prompt

Create a premium editorial photography Open Graph card for Twyne, landscape 1200:630 ratio. A warmly lit authentic writer's desk seen overhead, tactile ivory manuscript pages with restrained red proofreading marks, a fountain pen and red pencil, espresso in small ceramic cup at far right. Compose the objects across the right half, with left half clear ivory paper for large elegant deep vermilion serif wordmark 'Twyne' and a crisp black serif headline exactly 'Make room for your writing.' Small footer exactly 'twyne.love'. Natural afternoon light, subtle shadows, analog intimacy, warm paper black ink vermilion palette, realistic beautiful photography, editorial and restrained. No laptop, no extra readable text, no badges, no watermark. Typography very legible with generous safe margins.
export const TWYNE_SITE_ORIGIN = "https://twyne.love";
export const TWYNE_SOCIAL_IMAGE = `${TWYNE_SITE_ORIGIN}/assets/social/twyne-writers-desk-v1.jpg`;
export const TWYNE_SOCIAL_IMAGE_ALT =
  "Twyne — Make room for your writing. A sunlit writer's desk with annotated manuscript pages, a fountain pen, a red pencil, and coffee.";

const PRIVATE_ROUTE_ROOTS = new Set([
  "analysis",
  "apparatus",
  "auth",
  "dossier",
  "editor",
  "library",
  "onboarding",
  "personas",
  "privacy-ledger",
  "revisions",
  "rubric",
  "settings",
  "signin",
]);

/** Canonicals always identify the public origin and never preserve tracking. */
export function canonicalUrl(url: URL): string {
  const path =
    url.pathname === "/" ? "/" : `${url.pathname.replace(/\/+$/, "")}/`;
  return new URL(path, TWYNE_SITE_ORIGIN).href;
}

/** Workspace and authentication shells are useful to users, not search results. */
export function isPrivateWorkspacePath(pathname: string): boolean {
  const root = pathname.replace(/^\/+/, "").split("/", 1)[0] ?? "";
  return PRIVATE_ROUTE_ROOTS.has(root);
}

export const TWYNE_HOME_STRUCTURED_DATA = {
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      name: "Twyne",
      url: `${TWYNE_SITE_ORIGIN}/`,
      description:
        "A local-first editorial writing room for drafting with a brief, editorial personas, rubric review, and citation detection.",
    },
    {
      "@type": ["WebApplication", "SoftwareApplication"],
      name: "Twyne",
      url: `${TWYNE_SITE_ORIGIN}/`,
      image: TWYNE_SOCIAL_IMAGE,
      applicationCategory: "DesignApplication",
      operatingSystem: "Any",
      description:
        "A local-first writing workspace where a room of editorial personas reads from the writer's brief.",
      offers: {
        "@type": "Offer",
        price: "0",
        priceCurrency: "USD",
      },
    },
  ],
} as const;

