import { copyFile, mkdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("../", import.meta.url));
const project = `${root}social-preview-video/`;
const socialAssets = `${root}public/assets/social/`;
const overlay = await readFile(
  `${socialAssets}twyne-writers-desk-overlay.svg`,
  "utf8",
);

await mkdir(`${project}assets`, { recursive: true });
await copyFile(
  `${socialAssets}twyne-writers-desk-background-v1.jpg`,
  `${project}assets/desk-background.jpg`,
);
await copyFile(
  `${socialAssets}font-licenses.txt`,
  `${project}assets/font-licenses.txt`,
);

// Reuse the still card's actual SVG text and logo. Only the photograph moves;
// the registered, paused timeline can be sought to any frame by HyperFrames.
await writeFile(
  `${project}index.html`,
  `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=1200, height=630">
  <title>Twyne · Writer’s desk loop</title>
  <script src="assets/gsap.min.js"></script>
  <style>
    html, body { width: 100%; height: 100%; margin: 0; background: #faf3df; }
    * { box-sizing: border-box; }
    #root { position: relative; width: 100%; height: 100%; overflow: hidden; }
    .clip { position: absolute; inset: 0; width: 100%; height: 100%; }
    #desk-photo { display: block; width: 100%; height: 100%; object-fit: cover; transform-origin: 65% 50%; will-change: transform; }
    #branding { z-index: 1; }
    #branding > svg { display: block; width: 100%; height: 100%; }
  </style>
</head>
<body>
  <div id="root" data-composition-id="twyne-writers-desk" data-width="1200" data-height="630" data-start="0" data-duration="6">
    <div id="photograph" class="clip" data-start="0" data-duration="6" data-track-index="0" data-track-name="Desk photograph">
      <img id="desk-photo" src="assets/desk-background.jpg" alt="A sunlit writer’s desk with annotated manuscripts, pens, and coffee." data-layout-allow-overflow>
    </div>
    <div id="branding" class="clip" data-start="0" data-duration="6" data-track-index="1" data-track-name="Twyne logo and typography">
      ${overlay}
    </div>
  </div>
  <script>
    const timeline = gsap.timeline({ paused: true });
    timeline.fromTo('#desk-photo',
      { scale: 1, x: 0, y: 0 },
      { scale: 1.035, x: -4.2, y: 1.26, duration: 3, ease: 'sine.inOut', yoyo: true, repeat: 1 },
      0
    );
    window.__timelines['twyne-writers-desk'] = timeline;
  </script>
</body>
</html>`,
);

await writeFile(
  `${project}index.motion.json`,
  JSON.stringify(
    {
      duration: 6,
      assertions: [
        { kind: "appearsBy", selector: "#branding", bySec: 0.1 },
        { kind: "staysInFrame", selector: "#branding" },
        {
          kind: "keepsMoving",
          withinSelector: "#photograph",
          maxStaticSec: 2,
        },
      ],
    },
    null,
    2,
  ) + "\n",
);

console.log("Built the six-second desk composition from the shared card layers.");

